{"content":"package ledger

import "context"

func (l *Ledger) Transfer(ctx context.Context, id, from, to string, amount int64) (Receipt, error) {
	if err := ctx.Err(); err != nil {
		return Receipt{}, err
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	if err := ctx.Err(); err != nil {
		return Receipt{}, err
	}
	if r, ok := l.receipts[id]; ok {
		if r.From == from && r.To == to && r.Amount == amount {
			return r, nil
		}
		return Receipt{}, ErrConflict
	}
	if id == "" || from == "" || to == "" || from == to || amount <= 0 {
		return Receipt{}, ErrInvalid
	}
	fromBal, ok := l.balances[from]
	if !ok {
		return Receipt{}, ErrMissingAccount
	}
	if _, ok := l.balances[to]; !ok {
		return Receipt{}, ErrMissingAccount
	}
	if fromBal < amount {
		return Receipt{}, ErrInsufficientFunds
	}
	l.balances[from] = fromBal - amount
	l.balances[to] += amount
	r := Receipt{ID: id, From: from, To: to, Amount: amount, FromBalance: l.balances[from], ToBalance: l.balances[to]}
	l.receipts[id] = r
	return r, nil
}
