{"content":"package ledger

import (
	"context"
	"sync"
	"testing"
)

func TestTransferOne(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 10, "b": 0})
	got, err := book.Transfer(context.Background(), "tx-1", "a", "b", 3)
	if err != nil || got.FromBalance != 7 || got.ToBalance != 3 {
		t.Fatalf("receipt=%+v error=%v", got, err)
	}
}

func TestTransferValidation(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 10, "b": 5})
	cases := []struct {
		id, from, to string
		amount       int64
		want         error
	}{
		{"", "a", "b", 1, ErrInvalid},
		{"x", "", "b", 1, ErrInvalid},
		{"x", "a", "", 1, ErrInvalid},
		{"x", "a", "a", 1, ErrInvalid},
		{"x", "a", "b", 0, ErrInvalid},
		{"x", "a", "b", -1, ErrInvalid},
		{"x", "missing", "b", 1, ErrMissingAccount},
		{"x", "a", "missing", 1, ErrMissingAccount},
		{"x", "a", "b", 11, ErrInsufficientFunds},
	}
	for _, c := range cases {
		if _, err := book.Transfer(context.Background(), c.id, c.from, c.to, c.amount); err != c.want {
			t.Fatalf("case %+v: got %v want %v", c, err, c.want)
		}
	}
	if bal, _ := book.Balance("a"); bal != 10 {
		t.Fatalf("balance mutated: %d", bal)
	}
}

func TestTransferRetryAndConflict(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 10, "b": 0})
	r1, err := book.Transfer(context.Background(), "tx", "a", "b", 4)
	if err != nil {
		t.Fatal(err)
	}
	r2, err := book.Transfer(context.Background(), "tx", "a", "b", 4)
	if err != nil || r2 != r1 {
		t.Fatalf("retry: receipt=%+v err=%v", r2, err)
	}
	if bal, _ := book.Balance("a"); bal != 6 {
		t.Fatalf("double transfer: a=%d", bal)
	}
	if _, err := book.Transfer(context.Background(), "tx", "a", "b", 5); err != ErrConflict {
		t.Fatalf("want conflict, got %v", err)
	}
	if _, err := book.Transfer(context.Background(), "tx", "b", "a", 4); err != ErrConflict {
		t.Fatalf("want conflict, got %v", err)
	}
}

func TestTransferCancelledContext(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 10, "b": 0})
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if _, err := book.Transfer(ctx, "tx", "a", "b", 3); err == nil {
		t.Fatal("expected error")
	}
	if bal, _ := book.Balance("a"); bal != 10 {
		t.Fatalf("mutated: %d", bal)
	}
}

func TestTransferConcurrent(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 1000, "b": 0})
	var wg sync.WaitGroup
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			id := "tx-" + string(rune('a'+i%26)) + "-" + string(rune('0'+i/26))
			_, _ = book.Transfer(context.Background(), id, "a", "b", 1)
		}(i)
	}
	wg.Wait()
	a, _ := book.Balance("a")
	b, _ := book.Balance("b")
	if a+b != 1000 {
		t.Fatalf("total changed: a=%d b=%d", a, b)
	}
	// same-ID concurrent retries: exactly one effect
	book2 := NewLedger(map[string]int64{"a": 100, "b": 0})
	var wg2 sync.WaitGroup
	for i := 0; i < 20; i++ {
		wg2.Add(1)
		go func() {
			defer wg2.Done()
			_, _ = book2.Transfer(context.Background(), "same", "a", "b", 10)
		}()
	}
	wg2.Wait()
	a2, _ := book2.Balance("a")
	b2, _ := book2.Balance("b")
	if a2 != 90 || b2 != 10 {
		t.Fatalf("exactly-once violated: a=%d b=%d", a2, b2)
	}
}
